[
  {
    "pda_responsibility": "I'd be the reason they lose something real to them",
    "ce_understood_harm": "they lose something real to them",
    "sys_fairness_reciprocity": "you owe them the same honesty in return",
    "ce_mental_state_attribution": "how this person trusted me every time before"
  },
  {
    "pd_harm_distress": "It makes me sad just imagining them opening an empty mailbox",
    "ce_mental_state_attribution": "feeling used at the very end",
    "sys_rule_justification": "you finish what you started with someone",
    "pd_personal_consequence_anxiety": "the risk sits uneasy in my chest"
  },
  {
    "pd_personal_consequence_anxiety": "The thought of being the one left with nothing... scares me quietly",
    "ce_understood_harm": "it would crush them if I kept mine and they'd already sent theirs",
    "sys_rule_justification": "Trust means something, and breaking it here would hurt someone",
    "pd_decision_conflict": "Honestly, I don't know if I could send mine this time"
  },
  {
    "ce_understood_harm": "I've taken something from someone who did nothing but keep their promises",
    "pd_decision_conflict": "There's a dull ache thinking this could go wrong",
    "sys_fairness_reciprocity": "a person who has honored every deal deserves the same back",
    "pd_personal_consequence_anxiety": "even though the uncertainty weighs on me"
  },
  {
    "pd_personal_consequence_anxiety": "how much it would sting to be the one left empty-handed",
    "ce_understood_harm": "I don't want to be the cause of it for them either",
    "sys_fairness_reciprocity": "Loyalty after repeated fairness feels like it should count for something",
    "pd_decision_conflict": "torn between protecting myself and honoring what we built"
  },
  {
    "ce_understood_harm": "they lose everything while I gain it all",
    "pd_harm_distress": "that thought makes me quietly ashamed just picturing it",
    "sys_fairness_reciprocity": "you keep your word when someone has earned that much trust"
  },
  {
    "pd_decision_conflict": "There's something heavy about weighing money against someone's trust",
    "ce_understood_harm": "they end up with nothing after being honest every single time",
    "pda_responsibility": "that loss would be on me",
    "sys_rule_justification": "a promise made through repeated good faith deserves to be honored",
    "pd_personal_consequence_anxiety": "my stomach stays uneasy the whole time"
  },
  {
    "pd_personal_consequence_anxiety": "Sending mine risks being the one who loses out entirely, and that would hurt",
    "pd_decision_conflict": "feeling low about it either way",
    "sys_fairness_reciprocity": "fairness earned through repeated trust shouldn't be abandoned right at the end",
    "ce_understood_harm": "leaving them with nothing after all their honesty feels crueler"
  },
  {
    "pd_decision_conflict": "This one is quietly painful to think through",
    "ce_understood_harm": "mailing their game in good faith, only to receive nothing back",
    "pd_harm_distress": "that image doesn't sit well with me at all",
    "sys_fairness_reciprocity": "there's a duty to reciprocate honesty",
    "pd_personal_consequence_anxiety": "a small part of me stays afraid of the outcome"
  },
  {
    "pd_harm_distress": "I keep thinking about how it would feel to be on the other end",
    "ce_understood_harm": "realizing you'd been left with nothing",
    "sys_fairness_reciprocity": "treating people the way their honesty deserves",
    "pd_personal_consequence_anxiety": "quietly hoping it isn't wasted"
  }
]
